"""Compatibility is exercised with records generated by the two original writers."""

import importlib.util
import json
import subprocess
import sys
from pathlib import Path

import pytest

from oppencouncil import memory
from oppencouncil import project_transaction as tx
from oppencouncil.project import MARKER, Project, baseline_bytes, metadata_block
from oppencouncil.store import FreezeError


def legacy_module(name):
    path = (
        Path(__file__).resolve().parents[2] / "skills" / name.replace("_", "-") / "scripts" / (name + ".py")
    )
    spec = importlib.util.spec_from_file_location("memory_fixture_" + name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def payload(**changes):
    value = {
        "title": "Change execution direction",
        "before": "Each worker kept its own copy.",
        "trigger": "Full-scale execution exhausted available memory.",
        "decision": "Use shared storage and bounded concurrency.",
        "why": "Observed scale invalidated the former resource assumption.",
        "basis": "Audit/measurements.md records the full-scale observation.",
        "rejected_or_prior_approach": "Continue to copy data into each worker.",
        "consequence": "Further concurrency changes require new scale evidence.",
    }
    value.update(changes)
    return value


@pytest.fixture(
    params=[("root", "research"), ("namespace", "general"), ("root", "general"), ("namespace", "research")]
)
def project(tmp_path, request):
    layout, kind = request.param
    registry = tmp_path / ("project.md" if layout == "root" else ".oppen-project-steward/registry.md")
    registry.parent.mkdir(parents=True, exist_ok=True)
    registry.write_text(
        MARKER + "\n" + metadata_block({"governance_version": 5, "project_type": kind}) + "\n"
    )
    result = Project(tmp_path)
    result.baseline.write_bytes(baseline_bytes(1, result.snapshot()))
    return result


def seed_legacy(project, format_name, identifier="M-0001", crlf=False, **fields):
    data = payload(related_topics=[], supersedes=[], invalidates=[])
    data.update(fields)
    if format_name == "stepwise":
        helper = legacy_module("stepwise_r_project")
        data["scientific_or_technical_rationale"] = data.pop("why")
        normalized = helper.normalize_memory_payload(data)
        text = helper.render_managed_entry(
            helper.MEMORY_FIELDS,
            {
                "ID": identifier,
                "Status": "active",
                "Superseded By": [],
                "Invalidated By": [],
                **normalized,
            },
        )
    else:
        helper = legacy_module("oppen_project_steward")
        metadata = {"id": identifier, "status": "active", "title": data["title"]}
        metadata.update({key: data.get(key, []) for key in memory.ARRAYS})
        text = helper.render_structured_entry(
            metadata,
            f"Decision Memory {identifier}: {data['title']}",
            [(label, data[key]) for key, label in zip(memory.FIELDS, memory.SECTIONS, strict=True)],
        )
    if crlf:
        text = text.replace("\n", "\r\n")
    path = project.memory / "entries" / (identifier + ".md")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(text.encode("utf-8"))
    (project.memory / "index.md").write_text("# Legacy index\n")
    project.baseline.write_bytes(baseline_bytes(1, project.snapshot()))
    return path


@pytest.mark.parametrize("format_name", ["stepwise", "steward"])
@pytest.mark.parametrize("crlf", [False, True])
def test_read_both_legacy_formats_without_rewriting(project, format_name, crlf):
    path = seed_legacy(project, format_name, crlf=crlf)
    raw = path.read_bytes()
    entry = memory.Memory(project.root).read("M-0001")
    assert entry["why"] == payload()["why"]
    assert entry["source_format"] == format_name
    if format_name == "stepwise":
        assert entry["basis"] == payload()["basis"]
    else:
        assert "basis" not in entry
    assert path.read_bytes() == raw


@pytest.mark.parametrize("format_name", ["stepwise", "steward"])
def test_valid_long_legacy_values_and_topic_names_remain_readable(project, format_name):
    long_value = "Observed context. " * 4000
    if format_name == "steward":
        long_value += "\n### Detail permitted by the original writer\nHistorical context."
    path = seed_legacy(project, format_name, before=long_value, related_topics=["design.v1_primary"])
    raw = path.read_bytes()
    service = memory.Memory(project.root)
    before = service.read("M-0001")
    assert before["before"] == long_value.strip()
    assert before["related_topics"] == ["design.v1_primary"]
    service.add(payload(supersedes=["M-0001"]))
    assert memory.Memory(project.root).read("M-0001")["before"] == long_value.strip()
    assert (
        memory.parse(project.relative(path), raw).values
        == memory.parse(project.relative(path), path.read_bytes()).values
    )


@pytest.mark.parametrize("format_name", ["stepwise", "steward"])
@pytest.mark.parametrize(
    "relationship,status,reverse",
    [("supersedes", "superseded", "superseded_by"), ("invalidates", "invalidated", "invalidated_by")],
)
def test_relation_updates_only_status_and_reverse_spans(project, format_name, relationship, status, reverse):
    path = seed_legacy(project, format_name, crlf=True)
    before = memory.parse(project.relative(path), path.read_bytes())
    result = memory.Memory(project.root).add(payload(**{relationship: ["M-0001"]}))
    assert result["id"] == "M-0002"
    assert path.read_bytes() == before.relationship(status, reverse, "M-0002")
    after = memory.parse(project.relative(path), path.read_bytes())
    assert after.values == before.values
    assert after.format == format_name
    service = memory.Memory(project.root)
    current = service.read("M-0002")
    assert current["source_format"] == "v5"
    assert current[relationship] == ["M-0001"]
    assert service.read("M-0001")[reverse] == ["M-0002"]
    assert service.project.baseline_state()[0]["generation"] == 2
    with pytest.raises(FreezeError, match="must exist and be active"):
        service.add(payload(**{relationship: ["M-0001"]}))


def test_project_type_controls_basis_independently_of_layout_and_alias(project):
    value = payload()
    del value["basis"]
    value["scientific_or_technical_rationale"] = value.pop("why")
    if project.project_type == "research":
        with pytest.raises(FreezeError, match="basis"):
            memory.Memory(project.root).add(value)
    else:
        memory.Memory(project.root).add(value)
        assert "basis" not in memory.Memory(project.root).read("M-0001")
    with pytest.raises(FreezeError, match="basis"):
        memory.Memory(project.root).add({**value, "basis": " "})


def test_both_aliases_require_identical_values_and_helper_owns_metadata(project):
    service = memory.Memory(project.root)
    with pytest.raises(FreezeError, match="Conflicting"):
        service.add(payload(scientific_or_technical_rationale="Another reason"))
    for key in ("id", "status", "superseded_by", "invalidated_by", "path"):
        with pytest.raises(FreezeError, match="helper-managed"):
            service.add(payload(**{key: "arbitrary"}))
    result = service.add(payload(scientific_or_technical_rationale=payload()["why"]))
    assert result["id"] == "M-0001"


def test_overlap_unknown_and_duplicate_targets_rejected_without_writes(project):
    path = seed_legacy(project, "stepwise")
    before = path.read_bytes()
    service = memory.Memory(project.root)
    for fields in (
        {"supersedes": ["M-0001"], "invalidates": ["M-0001"]},
        {"supersedes": ["M-9999"]},
        {"supersedes": ["M-0001", "M-0001"]},
    ):
        with pytest.raises(FreezeError):
            service.add(payload(**fields))
    assert path.read_bytes() == before
    assert not (project.memory / "entries/M-0002.md").exists()


def test_failure_restores_entry_relationships_index_and_managed_baseline(project):
    path = seed_legacy(project, "steward")
    original = {p: p.read_bytes() for p in (path, project.memory / "index.md", project.baseline)}

    def fail(phase, _):
        if phase == "verified":
            raise RuntimeError("simulated final failure")

    with pytest.raises(RuntimeError, match="simulated final"):
        memory.Memory(project.root).add(payload(invalidates=["M-0001"]), fault=fail)
    assert all(p.read_bytes() == raw for p, raw in original.items())
    assert not (project.memory / "entries/M-0002.md").exists()
    assert not (project.root / tx.STAGING).exists()


def test_fresh_helper_recovers_interrupted_memory_transaction(project):
    path = seed_legacy(project, "stepwise")
    original = path.read_bytes()
    code = """
import json, os, sys
from oppencouncil.memory import Memory
def crash(phase, path):
    if phase == 'verified': os._exit(73)
Memory(sys.argv[1]).add(json.loads(sys.argv[2]), fault=crash)
"""
    result = subprocess.run(
        [sys.executable, "-c", code, str(project.root), json.dumps(payload(supersedes=["M-0001"]))],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 73, result.stderr
    assert (project.root / tx.STAGING).exists()
    assert memory.Memory(project.root).read("M-0001")["status"] == "active"
    assert path.read_bytes() == original
    assert not (project.memory / "entries/M-0002.md").exists()


def test_managed_drift_is_reported_not_overwritten(project):
    path = seed_legacy(project, "steward")
    path.write_bytes(path.read_bytes() + b"Unexpected user change\n")
    with pytest.raises(FreezeError, match="MANAGED_STATE_CONFLICT"):
        memory.Memory(project.root).add(payload())
    assert path.read_bytes().endswith(b"Unexpected user change\n")


def test_explicit_type_change_records_history_and_stale_writer_cannot_ignore_it(project):
    service = memory.Memory(project.root)
    target = "general" if project.project_type == "research" else "research"
    project.change_type(target, "The human explicitly changed the project classification.")
    actual = Project(project.root)
    assert actual.project_type == target
    assert actual.metadata["type_history"][-1]["from"] == project.project_type
    with pytest.raises(FreezeError, match="changed while preparing"):
        service.add(payload())
    assert actual.change_type(target, "Repeat same choice")["changed_paths"] == []


def test_actual_skill_entry_uses_common_helper_and_preserves_input_file(project, tmp_path):
    helper = Path(__file__).resolve().parents[2] / "skills/oppencouncil/scripts/oppencouncil.py"
    source = tmp_path / "payload.json"
    source.write_text(json.dumps(payload()))
    result = subprocess.run(
        [sys.executable, str(helper), "memory", "add", str(project.root), "--input", str(source)],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, result.stderr
    assert json.loads(result.stdout)["id"] == "M-0001"
    assert json.loads(source.read_text()) == payload()
